insert into legs (id, trip_id, position, base, name_alt, start_date, end_date, hotel_id, color, image, blurb) values
  ('b72de259-6b64-49fb-92bf-57a84eca5c04', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'Tokyo', '東京', '2026-10-21', '2026-10-26', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'blue', 'leg-tokyo', 'Five nights to land softly, shake off the flight and wander the city before heading for the mountains.'),
  ('3e00426a-e19c-4dce-91e0-270f12a7d611', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Lake Kawaguchiko', '河口湖', '2026-10-26', '2026-10-28', 'eaeeffed-b036-4e34-b4ef-8f83b403f5c2', 'sage', 'leg-kawaguchiko', 'Two slow nights by the lake under Mt Fuji. The big luggage goes ahead to Kyoto.'),
  ('2ac30fbd-6538-4eb7-9d26-b497a72892c0', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'Kyoto', '京都', '2026-10-28', '2026-11-11', 'a5837779-e484-46d3-829c-db1bd1151198', 'terracotta', 'leg-kyoto', 'The heart of the trip — two weeks with a base in Kyoto and day trips fanning out across Kansai.'),
  ('d4e38a54-2042-4443-9a00-9aea8e8ad201', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'Tokyo', '東京', '2026-11-11', '2026-11-13', '340bb5e0-37e2-4809-8063-e35084a6e899', 'blue', 'leg-tokyo-2', 'Back to Tokyo for two nights near the monorail, then the morning flight home.');
insert into hotels (id, trip_id, position, place_id, name, address, phone, url, check_in, check_out, wifi, door_code, reservation_ref, gallery, access, nearby, notes) values
  ('46ce0834-bf14-48b1-acfb-a3f800fc5a23', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'Section L Hamamatsuchō', 'Hamamatsuchō, Minato-ku, Tokyo — full address to add', '', '', '16:00', '10:00', '', '', '', '["hotel-section-l"]'::jsonb, '{"stationWalkMin":6,"grade":"flat","elevator":true,"note":"Hamamatsuchō (JR Yamanote / Keihin-Tōhoku) and the Haneda monorail terminal; Daimon (Toei) is closer to some units."}'::jsonb, '[{"type":"station","name":"Hamamatsuchō Station","walkMin":6,"gmapsQuery":"Hamamatsucho Station","note":"JR + Tokyo Monorail to Haneda"},{"type":"station","name":"Daimon Station","walkMin":4,"gmapsQuery":"Daimon Station Tokyo","note":"Toei Asakusa / Oedo lines"},{"type":"convenience","brand":"7-Eleven","name":"7-Eleven (nearest)","walkMin":2,"gmapsQuery":"7-Eleven Hamamatsucho"},{"type":"convenience","brand":"Lawson","name":"Lawson (nearest)","walkMin":3,"gmapsQuery":"Lawson Hamamatsucho"},{"type":"convenience","brand":"FamilyMart","name":"FamilyMart (nearest)","walkMin":3,"gmapsQuery":"FamilyMart Hamamatsucho"},{"type":"supermarket","name":"Supermarket (nearest)","walkMin":7,"gmapsQuery":"supermarket Hamamatsucho"},{"type":"pharmacy","name":"Pharmacy / drugstore","walkMin":5,"gmapsQuery":"drugstore Hamamatsucho"},{"type":"atm","name":"7-Bank ATM (accepts foreign cards)","walkMin":2,"gmapsQuery":"7 Bank ATM Hamamatsucho"},{"type":"courier","brand":"Yamato (Kuroneko)","name":"Yamato Transport service centre","walkMin":8,"gmapsQuery":"Yamato Transport Minato Hamamatsucho"},{"type":"laundry","name":"Coin laundry","walkMin":9,"gmapsQuery":"coin laundry Hamamatsucho"}]'::jsonb, 'First stay: 5 nights, 21–26 Oct. Ship the large cases from here to Kyoto on the 26th (or via the front desk the evening before).'),
  ('340bb5e0-37e2-4809-8063-e35084a6e899', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, '340bb5e0-37e2-4809-8063-e35084a6e899', 'Section L Hamamatsuchō — return', 'Hamamatsuchō, Minato-ku, Tokyo — full address to add', NULL, NULL, '16:00', '10:00', '', '', '', '["hotel-section-l"]'::jsonb, '{"stationWalkMin":6,"grade":"flat","elevator":true,"note":"Same area as the first stay — handy for the monorail to Haneda on departure morning."}'::jsonb, '[{"type":"station","name":"Hamamatsuchō Station","walkMin":6,"gmapsQuery":"Hamamatsucho Station","note":"Monorail to Haneda, ~13 min"},{"type":"convenience","brand":"7-Eleven","name":"7-Eleven (nearest)","walkMin":2,"gmapsQuery":"7-Eleven Hamamatsucho"},{"type":"atm","name":"7-Bank ATM","walkMin":2,"gmapsQuery":"7 Bank ATM Hamamatsucho"},{"type":"courier","brand":"Yamato (Kuroneko)","name":"Yamato Transport service centre","walkMin":8,"gmapsQuery":"Yamato Transport Minato Hamamatsucho"}]'::jsonb, 'Second stay: 2 nights, 11–13 Nov. Flight home 13 Nov, 10:00 — leave by ~07:30.'),
  ('eaeeffed-b036-4e34-b4ef-8f83b403f5c2', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'eaeeffed-b036-4e34-b4ef-8f83b403f5c2', 'Villa Yamitsuki', 'Kawaguchiko, Fujikawaguchiko, Yamanashi — full address to add', NULL, NULL, '15:00', '10:00', '', '', '', '["hotel-yamitsuki"]'::jsonb, '{"stationWalkMin":15,"grade":"gentle","elevator":false,"note":"Around the lake from Kawaguchiko Station — a taxi or the Retro Bus is easiest with bags. Confirm parking / pickup with the host."}'::jsonb, '[{"type":"station","name":"Kawaguchiko Station","walkMin":15,"gmapsQuery":"Kawaguchiko Station","note":"Fujikyu line + bus terminal; Retro Bus loops the lake"},{"type":"convenience","brand":"Lawson","name":"Lawson (nearest)","walkMin":8,"gmapsQuery":"Lawson Kawaguchiko"},{"type":"supermarket","name":"Supermarket (Max Valu / Ogino)","walkMin":12,"gmapsQuery":"supermarket Kawaguchiko"},{"type":"convenience","brand":"7-Eleven","name":"7-Eleven","walkMin":10,"gmapsQuery":"7-Eleven Kawaguchiko"},{"type":"atm","name":"Post office / 7-Bank ATM","walkMin":12,"gmapsQuery":"7 Bank ATM Kawaguchiko"},{"type":"courier","brand":"Yamato (Kuroneko)","name":"Yamato Transport (Fujikawaguchiko)","walkMin":14,"gmapsQuery":"Yamato Transport Fujikawaguchiko"}]'::jsonb, '2 nights, 26–28 Oct. This is the ryokan-style stay — see the genkan / tatami etiquette card. Onsen towel and slippers provided.'),
  ('a5837779-e484-46d3-829c-db1bd1151198', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'a5837779-e484-46d3-829c-db1bd1151198', 'ICY (Airbnb)', 'Kyoto — full address to add from the booking', NULL, NULL, '15:00', '11:00', '', '', '', '["hotel-icy"]'::jsonb, '{"stationWalkMin":8,"grade":"flat","elevator":false,"note":"Confirm the exact nearest subway/bus stop and the self-check-in steps with the host before arrival."}'::jsonb, '[{"type":"station","name":"Nearest subway / bus stop","walkMin":8,"gmapsQuery":"Kyoto subway station","note":"To confirm with host"},{"type":"convenience","brand":"Lawson","name":"Lawson (nearest)","walkMin":3,"gmapsQuery":"Lawson Kyoto"},{"type":"convenience","brand":"FamilyMart","name":"FamilyMart (nearest)","walkMin":4,"gmapsQuery":"FamilyMart Kyoto"},{"type":"supermarket","name":"Fresco / Life supermarket","walkMin":6,"gmapsQuery":"Fresco supermarket Kyoto"},{"type":"pharmacy","name":"Matsumoto Kiyoshi / drugstore","walkMin":6,"gmapsQuery":"drugstore Kyoto"},{"type":"atm","name":"7-Bank ATM","walkMin":3,"gmapsQuery":"7 Bank ATM Kyoto"},{"type":"courier","brand":"Yamato (Kuroneko)","name":"Yamato Transport service centre","walkMin":10,"gmapsQuery":"Yamato Transport Kyoto"},{"type":"laundry","name":"Coin laundry","walkMin":7,"gmapsQuery":"coin laundry Kyoto"}]'::jsonb, '14 nights, 28 Oct – 11 Nov. The big cases should be waiting here on the 28th. Base for all the day trips.');
