insert into journeys (id, trip_id, position, label, kind, date, to_leg_id, notes, access, steps, from_leg_id, luggage_id, backup_route, gmaps_directions, official_url) values
  ('181b5e52-7238-4645-913f-3433fe57159d', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'Warsaw → Tokyo', 'arrival', '2026-10-21', 'b72de259-6b64-49fb-92bf-57a84eca5c04', 'Overnight layover in Beijing. Day one is deliberately gentle.', '{}'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('e38e4e90-65b7-42d0-a08f-c32892548182', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Tokyo → Lake Kawaguchiko', 'transfer', '2026-10-26', '3e00426a-e19c-4dce-91e0-270f12a7d611', 'Sit on the right leaving Ōtsuki for the first Mt Fuji views.', '{"stationWalkMin":8,"grade":"flat","elevator":true,"connections":0,"note":"Direct, no change. Shinjuku is large — allow time to find the limited-express platform; lifts from the JR concourse."}'::jsonb, '[{"title":"Travel light","detail":"Only carry-on / overnight bags today — the big cases are already on their way to Kyoto."},{"title":"Reserve seats","detail":"All Fuji Excursion seats are reserved and it sells out in foliage season. Book ~1 month ahead."},{"title":"Arrive at Kawaguchiko","detail":"Retro Bus or taxi around the lake to Villa Yamitsuki — ~15 min."}]'::jsonb, 'b72de259-6b64-49fb-92bf-57a84eca5c04', '6e59cf68-b1c8-4a52-b363-1253666c2e32', 'JR Chūō to Ōtsuki, change to the Fujikyū line to Kawaguchiko (~2h20, hourly). Or the highway bus from Busta Shinjuku (~1h45, ≈ ¥2,200, also fully reserved).', 'https://www.google.com/maps/dir/Shinjuku+Station/Kawaguchiko+Station', 'https://www.jreast.co.jp/multi/en/routemaps/'),
  ('7f222542-c215-4d32-b168-1f3e2d0d943e', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'Lake Kawaguchiko → Kyoto', 'transfer', '2026-10-28', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'The luggage sent from Tokyo should be in Kyoto (or held at the Yamato centre) — check the Luggage list.', '{"stationWalkMin":8,"grade":"flat","elevator":true,"connections":1,"note":"One change at Mishima. Bus arrives at the north exit; follow signs to the Shinkansen gates. Lifts on both sides."}'::jsonb, '[{"title":"Book the liner bus","detail":"The Mishima ⇄ Kawaguchiko liner sells out — reserve at Kawaguchiko Station a day or two ahead."},{"title":"Not all Hikari stop at Mishima","detail":"Roughly one direct Hikari every 1–2 hours. Pick the train first, then match the bus to it."},{"title":"Grab an ekiben","detail":"Buy lunch at Mishima before the platform."}]'::jsonb, '3e00426a-e19c-4dce-91e0-270f12a7d611', NULL, 'Fujikyū line to Ōtsuki → JR to Shin-Yokohama → Nozomi to Kyoto (~4h, two extra changes). Slower but every-few-minutes frequency.', 'https://www.google.com/maps/dir/Kawaguchiko+Station/Kyoto+Station', 'https://smart-ex.jp/en/'),
  ('844d0c9f-a13d-49c6-8776-3858750d83b2', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'Kyoto → Tokyo', 'transfer', '2026-11-11', 'd4e38a54-2042-4443-9a00-9aea8e8ad201', 'Two nights in Tokyo, then home on the 13th.', '{"stationWalkMin":5,"grade":"flat","elevator":true,"connections":1,"note":"Change at Tokyo Station to the Yamanote line (~4 min to Hamamatsuchō). Or ride to Shinagawa. Lifts throughout."}'::jsonb, '[{"title":"Ship the big cases first","detail":"Drop the large luggage at a Yamato centre or konbini on the morning of the 11th — it reaches Section L by the 12th."},{"title":"Reserve seats","detail":"Book on smartEX. Sit on the right (D/E) leaving Kyoto for Mt Fuji around Mishima."}]'::jsonb, '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'e479e0bb-9788-4f0d-8752-c39f0f0603c2', 'Hikari (same route, ~20 min slower, slightly cheaper). Or fly Itami/Kansai → Haneda.', 'https://www.google.com/maps/dir/Kyoto+Station/Hamamatsucho+Station', 'https://smart-ex.jp/en/'),
  ('9c3c79e3-514e-476b-833d-0eb20ec7efb0', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 4, 'Tokyo → Warsaw', 'departure', '2026-11-13', NULL, 'Departs Tokyo on the 13th, layover in Beijing, home on the 14th.', '{}'::jsonb, '[]'::jsonb, 'd4e38a54-2042-4443-9a00-9aea8e8ad201', NULL, NULL, NULL, NULL);
insert into luggage (id, trip_id, position, label, from_hotel_id, to_hotel_id, carrier, send_by, expected_arrival, tracking_no, office_address, status, notes) values
  ('6e59cf68-b1c8-4a52-b363-1253666c2e32', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'Large cases · Tokyo → Kyoto', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'a5837779-e484-46d3-829c-db1bd1151198', 'Yamato Transport (Kuroneko Takkyūbin)', '2026-10-26', '2026-10-28', '', 'Yamato service centre near Section L Hamamatsuchō — address to confirm', 'planned', 'Hand in at the hotel or a Yamato centre on the morning of the 26th (or the evening of the 25th). Tokyo→Kyoto is next-day, so it would arrive on the 27th — a day before check-in. Options: (a) ask the ICY host to receive it, or (b) address it to the nearest Yamato centre to Kyoto and collect with passport on the 28th. Decide with the host in advance.'),
  ('e479e0bb-9788-4f0d-8752-c39f0f0603c2', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Large cases · Kyoto → Tokyo', 'a5837779-e484-46d3-829c-db1bd1151198', '340bb5e0-37e2-4809-8063-e35084a6e899', 'Yamato Transport (Kuroneko Takkyūbin)', '2026-11-11', '2026-11-12', '', 'Yamato service centre near ICY, Kyoto — address to confirm', 'planned', 'No front desk at ICY — drop the cases yourself at a Yamato centre or a konbini (7-Eleven / FamilyMart / Lawson all accept Yamato) on the morning of the 11th before catching the Shinkansen. Arrives at Section L on the 12th; the desk there will hold it.');
insert into days (id, trip_id, position, date, kind, city, leg_id, hotel_id, title, summary, morning, afternoon, evening, packing_reminder, checklist, reservation_ids, journey_id, day_trip_id) values
  ('cf6e16b5-78e4-4b89-bf32-06b678c8853b', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, '2026-10-21', 'arrival', 'Tokyo', 'b72de259-6b64-49fb-92bf-57a84eca5c04', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'Arrival', 'In via Beijing on the red-eye. Get connected, drop the bags, stay upright until a normal bedtime.', '[{"time":"07:00","title":"Land at Haneda","note":"Off the Beijing flight. Pick up eSIM data / pocket wifi. Buy Suica or Welcome Suica at the machines.","placeId":"70b58de1-8d7e-448d-a8c3-16f9ac4e9807"},{"time":"08:30","title":"Monorail to Hamamatsuchō","note":"~13 min from Haneda; short walk to Section L. Bags may not be ready for check-in — ask to store them."}]'::jsonb, '[{"time":"12:00","title":"Slow lunch nearby, then a flat walk","note":"Daylight and movement beat the jet lag. Nothing that needs energy or a booking."},{"time":"15:00","title":"Check in, unpack, shower","placeId":"46ce0834-bf14-48b1-acfb-a3f800fc5a23"}]'::jsonb, '[{"time":"18:00","title":"Easy first dinner nearby","note":"Within a 10-minute walk — konbini run for breakfast supplies after."},{"time":"20:30","title":"Early night","note":"You''ve been up all night — but try to hold out to ~21:30."}]'::jsonb, 'Keep the day bag light for the whole Tokyo leg — laundry on ~day 4.', '["Activate eSIM","Top up Suica (¥3,000)","Photograph passport + landing stamp"]'::jsonb, '[]'::jsonb, NULL, NULL),
  ('6616767d-17a7-4bf4-b4ad-f405bd43e2db', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, '2026-10-22', 'base', 'Tokyo', 'b72de259-6b64-49fb-92bf-57a84eca5c04', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'Old Tokyo', 'Asakusa and the low city — a gentle, walkable first full day.', '[{"time":"08:30","title":"Sensō-ji before the crowds","placeId":"4c2ddf06-27d0-4178-8cfc-ca05ccf4730d"}]'::jsonb, '[{"title":"Kappabashi kitchen street, then the Sumida riverside"}]'::jsonb, '[{"title":"Dinner in Asakusa or back near Hamamatsuchō"}]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('33785ba3-a03b-4c3d-9a23-fb6f7a7771e6', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, '2026-10-23', 'base', 'Tokyo', 'b72de259-6b64-49fb-92bf-57a84eca5c04', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'West side', 'Meiji Jingū, Harajuku, and whatever else the day wants.', '[{"time":"09:00","title":"Meiji Jingū","placeId":"8e05b4f6-53b3-4eb6-96a8-78b881b8134c"}]'::jsonb, '[{"title":"Omotesandō → Shibuya","placeId":"51714a8c-1ead-4275-8417-162b92dc8dbe"}]'::jsonb, '[{"title":"Shimokitazawa for dinner and record shops","placeId":"6c2de40d-263a-4585-bad9-29d9e77429ea"}]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('8be14d26-8ad5-4629-82ba-ab6f08d940db', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, '2026-10-24', 'base', 'Tokyo', 'b72de259-6b64-49fb-92bf-57a84eca5c04', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'East side & coffee', 'Kiyosumi gardens, the coffee list, and a laundry run before the mountains.', '[{"time":"10:00","title":"Kiyosumi Teien garden","placeId":"d669a616-c754-4633-bc22-fb93370a31fb"}]'::jsonb, '[{"title":"Coffee crawl — Kiyosumi / Kuramae / Nakameguro","placeId":"fcd71113-e149-4927-b931-989570e4aca7"}]'::jsonb, '[{"title":"Laundry night — coin laundry near the hotel"}]'::jsonb, 'Run a wash tonight so everything''s dry before Kawaguchiko.', NULL, '[]'::jsonb, NULL, NULL),
  ('391b0b1e-7bf1-4afe-8a7f-adc86f11f823', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 4, '2026-10-25', 'base', 'Tokyo', 'b72de259-6b64-49fb-92bf-57a84eca5c04', '46ce0834-bf14-48b1-acfb-a3f800fc5a23', 'Open day', 'Flex day — a museum, the backstreets, more coffee, or just wandering. Repack tonight.', '[]'::jsonb, '[{"title":"Tokyo National Museum, Ueno","placeId":"157635c0-9a14-4bdd-b74e-985f9b7a6605"}]'::jsonb, '[{"title":"Split the luggage","note":"Overnight bag for Kawaguchiko; everything else in the big cases for Yamato tomorrow."}]'::jsonb, NULL, '["Repack: overnight bag vs big cases","Fill in the Yamato slip (to ICY / Yamato centre, Kyoto)","Confirm Fuji Excursion seats"]'::jsonb, '[]'::jsonb, NULL, NULL),
  ('d643ad65-0138-4ac8-b349-658b99eebcdd', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 5, '2026-10-26', 'travel', 'Lake Kawaguchiko', '3e00426a-e19c-4dce-91e0-270f12a7d611', 'eaeeffed-b036-4e34-b4ef-8f83b403f5c2', 'To the lake', 'Ship the big cases, then the Fuji Excursion to Kawaguchiko. Afternoon by the water.', '[{"time":"08:00","title":"Hand the large cases to Yamato","note":"At the hotel or a nearby centre."},{"time":"08:30","title":"Fuji Excursion from Shinjuku","placeId":"a90bc2b2-196f-4063-a26a-8553ef37f1e2"}]'::jsonb, '[{"time":"10:30","title":"Check in area / drop bags at Villa Yamitsuki","placeId":"eaeeffed-b036-4e34-b4ef-8f83b403f5c2"},{"title":"Ōishi Park and the lakeshow path","placeId":"ec10e6da-b5e9-44a0-9630-fcab2a88752d"}]'::jsonb, '[{"title":"Onsen, then dinner","note":"See the genkan / tatami etiquette card."}]'::jsonb, NULL, '["Yamato tracking number saved","Overnight bag only"]'::jsonb, '[]'::jsonb, 'e38e4e90-65b7-42d0-a08f-c32892548182', NULL),
  ('669baffb-883c-4cfa-8820-4465e1ce7aeb', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 6, '2026-10-27', 'base', 'Lake Kawaguchiko', '3e00426a-e19c-4dce-91e0-270f12a7d611', 'eaeeffed-b036-4e34-b4ef-8f83b403f5c2', 'Fuji day', 'Chūreitō pagoda at first light, the ropeway, and a slow lake loop.', '[{"time":"06:30","title":"Chūreitō Pagoda for sunrise on Fuji","note":"Clearest air is early. ~400 steps up.","placeId":"f5354bdc-9381-4a3e-86db-fff6cd47942e"}]'::jsonb, '[{"title":"Mt Kachi Kachi ropeway + lakeside lunch","placeId":"262dbe1b-e4d4-41a5-9abc-85bbd6227558"}]'::jsonb, '[{"title":"Last onsen; repack for Kyoto"}]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('f61c0d1b-6e05-4428-8546-a9a1cd1bcbd8', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 7, '2026-10-28', 'travel', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'To Kyoto', 'Liner bus to Mishima, Hikari to Kyoto. Settle in, find the konbini, gentle evening.', '[{"time":"09:40","title":"Mishima Liner bus from Kawaguchiko","placeId":"c2501b79-2fda-46ac-8d7d-86cd81c304a2"}]'::jsonb, '[{"time":"12:10","title":"Hikari: Mishima → Kyoto","placeId":"34d2cdc9-0374-47a3-bc4e-31dd4dc83dc7"},{"time":"15:00","title":"Check in to ICY; confirm the luggage arrived","placeId":"a5837779-e484-46d3-829c-db1bd1151198"}]'::jsonb, '[{"title":"Nishiki Market for dinner bits, or Pontochō","placeId":"b53c9222-533b-4350-be66-8ac4beb0e09b"}]'::jsonb, NULL, '["Big cases received / located","Learn the walk to the nearest station","Buy a Kyoto bus/subway IC top-up"]'::jsonb, '[]'::jsonb, '7f222542-c215-4d32-b168-1f3e2d0d943e', NULL),
  ('ec39f797-4696-4b6b-afcd-6e6b68d3978f', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 8, '2026-10-29', 'daytrip', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Southern Higashiyama', 'Kiyomizu-dera down through the Sannenzaka lanes to Gion. The classic Kyoto walk.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, 'bb4e3c5a-729c-4a78-9da2-98677537361b'),
  ('13ad177a-aa5a-4fd8-9500-e971bf944002', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 9, '2026-10-30', 'base', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Fushimi Inari & Tōfuku-ji', 'Torii gates before 8, then the maple ravine at Tōfuku-ji as it starts to turn.', '[{"time":"07:30","title":"Fushimi Inari — up to the Yotsutsuji viewpoint","placeId":"13031117-2827-439d-b5e2-ecd954ae5e38"}]'::jsonb, '[{"title":"Tōfuku-ji Tsūten-bridge and gardens","placeId":"c502fbc3-74da-4386-90aa-19f461ec73de"}]'::jsonb, '[{"title":"Coffee at Weekenders, dinner downtown","placeId":"f4b1817b-6641-45e9-b9c4-aa119eb67b40"}]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('97eb73a3-0954-40f2-9d7b-5ddda4358dde', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 10, '2026-10-31', 'daytrip', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Arashiyama', 'Bamboo grove at opening, Tenryū-ji garden, the Sagano train if seats are free.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, 'fbe52a3c-e549-49ce-9d23-0a8a0e7b1cf9'),
  ('ede718c5-7d20-4d0b-b864-a0d13a5aefb3', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 11, '2026-11-01', 'base', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Central Kyoto', 'A slower city day — Nijō Castle, Nishiki, the coffee list, Pokémon Center at Takashimaya.', '[{"title":"Nijō Castle","placeId":"4b90656b-45f6-40e2-9bc3-ca52e966370a"}]'::jsonb, '[{"title":"Nishiki Market + Teramachi arcades","placeId":"b53c9222-533b-4350-be66-8ac4beb0e09b"}]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('138adf43-b7be-4df7-876a-94ffb99c94e2', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 12, '2026-11-02', 'daytrip', 'Nara', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Nara', 'Tōdai-ji''s Great Buddha, the deer, Kasuga''s lanterns, Isuien garden.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, '4232d295-9d48-4b7a-80d0-b4f74b37fcef'),
  ('1ebf3dd0-582a-4a91-a4d2-4ef4f53ddf02', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 13, '2026-11-03', 'base', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Culture Day', 'National holiday — expect crowds at the big sights. Good day for a museum, the Kyoto Railway Museum, or the quieter west of the city.', '[{"title":"Kyoto Railway Museum or the Manga Museum","note":"Indoor, holiday-proof."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('6e281f1e-3f30-4eb8-ae4b-570c553f474f', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 14, '2026-11-04', 'daytrip', 'Uji', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Uji', 'Byōdō-in''s Phoenix Hall, the riverside, and the best matcha of the trip.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, '4437747b-f55d-4c93-a30d-f03dd589e45a'),
  ('696cb7f0-629a-4258-ad39-c25169acb310', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 15, '2026-11-05', 'daytrip', 'Ohara', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Ōhara', 'Bus north to the moss gardens of Sanzen-in — foliage peaks here first.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, 'cdc0cdbb-0bcc-460a-8205-5dc4ade6aabb'),
  ('1fa55a85-cdef-4f12-9dee-eea90eb3a8b4', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 16, '2026-11-06', 'base', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Northern Higashiyama', 'Ginkaku-ji, the Philosopher''s Path, Eikan-dō for its famous maples — walk south all afternoon.', '[{"title":"Ginkaku-ji","placeId":"174e383f-7d64-4bf9-bfb5-31f7c0f5703b"}]'::jsonb, '[{"title":"Philosopher''s Path","placeId":"be49ac5c-b0f0-4349-8522-d8746728dfa7"},{"title":"Eikan-dō (Zenrin-ji)","placeId":"354e6c42-6bb7-46f1-827d-843301298cf5"}]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('cd9c5919-08d2-4dc2-bdf6-7421b51a76cd', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 17, '2026-11-07', 'daytrip', 'Kurama & Kibune', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Kurama → Kibune', 'The little mountain railway, the temple-to-shrine hike over the ridge, kaiseki by the river.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, '2d92497b-9089-431d-a5ba-7a8c1bf99a72'),
  ('46f7640d-9f5f-4120-a185-2a5b8cabf28f', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 18, '2026-11-08', 'daytrip', 'Osaka', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Osaka', 'Kuromon market, the castle, Dōtonbori after dark. Loud, fun, a change of pace.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, 'af1fd7b9-7668-4ce5-b502-7456f7dea604'),
  ('b3835335-2f92-4a69-b66f-8aa70306be0f', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 19, '2026-11-09', 'base', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Open day', 'A second pass at whatever earned it — Arashiyama foliage, Kinkaku-ji, a quiet temple, or nothing at all.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL),
  ('ae459f9e-6cd8-4981-b5e6-5ac1cbf7b4d5', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 20, '2026-11-10', 'base', 'Kyoto', '2ac30fbd-6538-4eb7-9d26-b497a72892c0', 'a5837779-e484-46d3-829c-db1bd1151198', 'Last Kyoto day', 'Favourites, last shopping, tax-free paperwork, and repacking. Ship the big cases tomorrow morning.', '[]'::jsonb, '[]'::jsonb, '[{"title":"Farewell dinner","note":"Book something — Pontochō or a counter place."}]'::jsonb, NULL, '["Tax-free receipts together with passports","Repack; big cases ready for Yamato","Fill in the Kyoto → Tokyo Yamato slip"]'::jsonb, '[]'::jsonb, NULL, NULL),
  ('ac1688c0-18dc-4164-8543-4f8aa9c7c70e', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 21, '2026-11-11', 'travel', 'Tokyo', 'd4e38a54-2042-4443-9a00-9aea8e8ad201', '340bb5e0-37e2-4809-8063-e35084a6e899', 'Back to Tokyo', 'Ship the cases, Nozomi to Tokyo, check in near the monorail. Afternoon free.', '[{"time":"08:30","title":"Drop big cases at a Yamato centre / konbini","placeId":"a5837779-e484-46d3-829c-db1bd1151198"},{"time":"10:30","title":"Nozomi: Kyoto → Tokyo","placeId":"6c2ed239-7e81-4005-a71a-bf3fd2264dea"}]'::jsonb, '[{"title":"Check in at Section L, then last-day Tokyo plans","placeId":"340bb5e0-37e2-4809-8063-e35084a6e899"}]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, '844d0c9f-a13d-49c6-8776-3858750d83b2', NULL),
  ('f8b49c63-a6b1-4c7b-88f7-526a9647f0c9', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 22, '2026-11-12', 'base', 'Tokyo', 'd4e38a54-2042-4443-9a00-9aea8e8ad201', '340bb5e0-37e2-4809-8063-e35084a6e899', 'Last full day', 'Whatever Tokyo you missed the first time. Collect the shipped cases at the desk. Pack tonight.', '[]'::jsonb, '[]'::jsonb, '[{"title":"Final dinner; early-ish night before the flight"}]'::jsonb, NULL, '["Confirm big cases arrived at the desk","Check in online for the flight","Spend or change leftover coins"]'::jsonb, '[]'::jsonb, NULL, NULL),
  ('2cc8274b-a7ae-4c32-bfea-ace1c0015873', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 23, '2026-11-13', 'departure', 'Tokyo', 'd4e38a54-2042-4443-9a00-9aea8e8ad201', '340bb5e0-37e2-4809-8063-e35084a6e899', 'Fly home', 'Monorail to Haneda for the 10:00 departure.', '[{"time":"07:15","title":"Check out","placeId":"340bb5e0-37e2-4809-8063-e35084a6e899"},{"time":"07:30","title":"Monorail to Haneda","placeId":"70b58de1-8d7e-448d-a8c3-16f9ac4e9807"},{"time":"10:00","title":"Flight home"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, '[]'::jsonb, NULL, NULL);
insert into day_trips (id, trip_id, position, name, name_alt, city, image, blurb, stats, get_there, return_options, see, eat, route, map_ref, checklist) values
  ('bb4e3c5a-729c-4a78-9da2-98677537361b', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'Southern Higashiyama', '東山', 'Kyoto', 'dt-kyoto', 'The postcard walk: Kiyomizu-dera on its stilts, down the stone lanes of Sannenzaka and Ninenzaka, through Maruyama Park to Gion and the Shirakawa canal.', '{"travelTimeMin":20,"walkKm":5,"difficulty":"moderate","elevationNote":"Steady climb to Kiyomizu, then steps and slopes through the lanes.","lastTrainBack":"In the city — buses run late; Keihan Gion-Shijō until ~23:30.","reservation":"none","bestMonths":"Late Nov for maples; any time for the lanes — earliest is quietest.","weatherNote":"Exposed hillside — sun hat or umbrella. Sunset light on Yasaka Pagoda is worth timing for."}'::jsonb, '["City bus 100 / 206 to Gojō-zaka or Kiyomizu-michi (~15 min from Kyoto Station).","Or Keihan to Kiyomizu-Gojō and walk up (~12 min)."]'::jsonb, '["Keihan from Gion-Shijō","Bus 206 from Gion","Walk down to Sanjō for dinner"]'::jsonb, '[{"name":"Kiyomizu-dera","placeId":"40523dc4-d923-49d4-ac7e-02182267c4fe","note":"Open from 06:00 — go first."},{"name":"Sannenzaka & Ninenzaka","note":"Preserved lanes; touristy by 10:00."},{"name":"Kōdai-ji","note":"Worth it for the garden; night illumination in Nov."},{"name":"Gion & Shirakawa canal","placeId":"be49ac5c-b0f0-4349-8522-d8746728dfa7","note":"Best in late afternoon."}]'::jsonb, '[{"name":"% Arabica Higashiyama","note":"Tiny; expect a queue."},{"name":"Kasagiya","note":"Old teahouse on Ninenzaka for warabi-mochi."}]'::jsonb, 'Gojō-zaka → Kiyomizu-dera → Sannenzaka → Ninenzaka → Kōdai-ji → Maruyama Park → Yasaka Shrine → Gion → Shirakawa.', 'Southern Higashiyama', '["Go for opening at Kiyomizu","Cash for the lanes","Comfortable shoes — all stone"]'::jsonb),
  ('4232d295-9d48-4b7a-80d0-b4f74b37fcef', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Nara', '奈良', 'Nara', 'dt-nara', 'Japan''s first capital: the Great Buddha of Tōdai-ji, a park full of bowing deer, the lantern-lined approach to Kasuga Taisha, and the quiet moss of Isuien.', '{"travelTimeMin":45,"walkKm":7,"difficulty":"moderate","elevationNote":"Gentle rise through the park; a longer climb if you go up to Nigatsu-dō for the view.","lastTrainBack":"Kintetsu / JR to Kyoto until ~23:00.","reservation":"recommended","bestMonths":"Mid-Nov for the park''s maples and ginkgo.","weatherNote":"Open parkland — colder in the wind than the city. Deer crackers are ¥200 from stalls."}'::jsonb, '["Kintetsu Limited Express, Kyoto → Kintetsu-Nara, ~35 min (reserved seat, ~¥1,160). Departs from Kintetsu Kyoto Station above the JR station.","Or JR Miyakoji Rapid, Kyoto → Nara, ~45 min, no reservation."]'::jsonb, '["Kintetsu Limited Express (reserve on the way out for the return too)","JR Rapid — walk from JR Nara"]'::jsonb, '[{"name":"Tōdai-ji — Daibutsuden","placeId":"477b4a03-52a0-4df8-b544-85a06106ec7d","note":"Opens 07:30 in autumn."},{"name":"Nara Park & Nandaimon","placeId":"cd13bd10-8296-41d5-b8e2-c497ddf26dbc"},{"name":"Kasuga Taisha","note":"3,000 lanterns; the approach path is the best part."},{"name":"Isuien Garden","note":"Small, ticketed, almost empty. The highlight for some."}]'::jsonb, '[{"name":"Naramachi lunch","note":"Machiya cafés south of Sarusawa Pond."},{"name":"Mizuya Chaya","note":"Warm udon inside the park near Kasuga."}]'::jsonb, 'Kintetsu-Nara → Isuien → Tōdai-ji → Nigatsu-dō viewpoint → Kasuga Taisha → Naramachi → station.', 'Nara', '["Reserve the Kintetsu seat","Small notes for deer crackers","Watch bags — the deer will investigate"]'::jsonb),
  ('af1fd7b9-7668-4ce5-b502-7456f7dea604', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'Osaka', '大阪', 'Osaka', 'dt-osaka', 'A loud, hungry counterpoint to Kyoto. Kuromon market for breakfast, the castle and its park, then Dōtonbori and Shinsekai after dark for takoyaki and kushikatsu.', '{"travelTimeMin":30,"walkKm":8,"difficulty":"easy","lastTrainBack":"JR Special Rapid to Kyoto until ~23:40; Hankyu to Kawaramachi until ~00:00.","reservation":"none","bestMonths":"Any — it''s a city day, weather-independent.","weatherNote":"Mostly covered arcades if it rains. Castle park is the only exposed stretch."}'::jsonb, '["JR Special Rapid, Kyoto → Ōsaka, ~29 min, every ~15 min, ~¥580.","Or Hankyu Limited Express, Kyoto-Kawaramachi → Ōsaka-Umeda, ~45 min, ~¥410."]'::jsonb, '["JR Special Rapid from Ōsaka Station","Hankyu from Umeda","Keihan from Yodoyabashi (for Gion-side)"]'::jsonb, '[{"name":"Kuromon Ichiba market","note":"Go before 11:00."},{"name":"Osaka Castle & park","note":"Skip the keep queue; the grounds are the point."},{"name":"Dōtonbori & Hōzenji Yokochō","placeId":"b721c67b-4008-4bcb-afd3-6b325ffabb3a"},{"name":"Shinsekai / Tsūtenkaku","note":"Kushikatsu — don''t double-dip the sauce."}]'::jsonb, '[{"name":"Takoyaki on Dōtonbori","note":"Wanaka or Kōgaryū."},{"name":"Okonomiyaki","note":"Mizuno on Dōtonbori, usually a wait."}]'::jsonb, 'Kuromon → Nipponbashi → Dōtonbori (day) → Osaka Castle → back to Namba/Shinsekai for dinner.', 'Osaka', '["Go hungry","IC card topped up","Cash for market stalls"]'::jsonb),
  ('4437747b-f55d-4c93-a30d-f03dd589e45a', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'Uji', '宇治', 'Uji', 'dt-uji', 'Half a day south for the Phoenix Hall of Byōdō-in — the building on the ¥10 coin — a walk along the fast green Uji river, and the two UNESCO shrines on the far bank.', '{"travelTimeMin":20,"walkKm":4,"difficulty":"easy","lastTrainBack":"JR Nara line to Kyoto until ~23:00.","reservation":"none","bestMonths":"Mid-Nov along the river.","weatherNote":"Riverside can be breezy. Byōdō-in''s pond reflects best on a still morning."}'::jsonb, '["JR Nara Line Rapid, Kyoto → Uji, ~20 min, ~¥240.","Or Keihan Uji line via Chūshojima (more scenic, ~35 min)."]'::jsonb, '["JR from Uji","Keihan from Keihan-Uji (closer to Byōdō-in)"]'::jsonb, '[{"name":"Byōdō-in & Phoenix Hall","placeId":"d10c6283-1ea5-446c-a060-155c648be2a9","note":"Timed entry for the hall interior — book on arrival."},{"name":"Uji Bridge & Tō-no-shima island","note":"Oldest bridge site in Japan."},{"name":"Ujigami Shrine","note":"Small UNESCO shrine, 10 min across the river."}]'::jsonb, '[{"name":"Soba or unagi near Byōdō-in","note":"The lane to the temple has a row of old restaurants."},{"name":"Nakamura-ken","note":"Riverside sweets shop if you want something small."}]'::jsonb, 'Uji Station → Byōdō-in → riverside → Ujigami Shrine → Kōshō-ji lane → station.', 'Uji', '["Byōdō-in hall ticket on arrival","Cash for the small shops"]'::jsonb),
  ('cdc0cdbb-0bcc-460a-8205-5dc4ade6aabb', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 4, 'Ōhara', '大原', 'Ōhara', 'dt-ohara', 'A farming valley in the northern hills. Sanzen-in''s moss garden and maples, the nuns'' temple of Jakkō-in, and a much slower pace than the city. Foliage turns here first.', '{"travelTimeMin":70,"walkKm":5,"difficulty":"moderate","elevationNote":"Uphill lane from the bus stop to Sanzen-in, then garden steps.","lastTrainBack":"No train — the last Kyoto Bus back leaves Ōhara around 18:20 (earlier in the day the timetable thins out; check on arrival).","reservation":"none","bestMonths":"Early–mid Nov — a week or two ahead of the city.","weatherNote":"Noticeably colder than Kyoto; often misty in the morning, which suits it. Dress warm."}'::jsonb, '["Kyoto Bus 17 from Kyoto Station (C3), ~60–75 min, ~¥560.","Faster: subway to Kokusaikaikan, then Kyoto Bus 19, ~25 min."]'::jsonb, '["Kyoto Bus 17 back to Kyoto Station — note the last departure when you arrive.","Bus 19 to Kokusaikaikan + subway (last around 19:00)."]'::jsonb, '[{"name":"Sanzen-in","placeId":"d1596a77-67be-4f59-a741-b02e6485268e","note":"Moss garden with the little Jizō figures; the reason to come."},{"name":"Hōsen-in","note":"Sit for tea in front of the framed-garden view."},{"name":"Jakkō-in","note":"15 min walk the other side of the valley; quiet."}]'::jsonb, '[{"name":"Soba near the Sanzen-in approach","note":"A handful of shops; close by ~16:00."}]'::jsonb, 'Ōhara bus stop → Sanzen-in → Hōsen-in → valley walk → Jakkō-in → bus stop.', 'Ohara', '["Photograph the return bus timetable on arrival","Warm layer + gloves","Cash — little is card-friendly"]'::jsonb),
  ('2d92497b-9089-431d-a5ba-7a8c1bf99a72', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 5, 'Kurama & Kibune', '鞍馬・貴船', 'Kurama & Kibune', 'dt-kurama', 'Ride the two-carriage mountain railway to Kurama, climb through Kurama-dera and its cedar roots, and drop down the far side to the lantern-lit shrine and ryokan of Kibune.', '{"travelTimeMin":40,"walkKm":4,"difficulty":"hilly","elevationNote":"~250 m of climbing from Kurama over the ridge, then a steep descent to Kibune. Roots, steps, uneven ground — proper shoes.","lastTrainBack":"Eizan line from Kibune-guchi to Demachiyanagi runs until ~21:00, but the trail is unlit and closes at dusk — be off the mountain by 16:00 (sunset ~16:45).","reservation":"recommended","bestMonths":"Mid-Nov; the Eizan ''maple tunnel'' between Ichihara and Ninose is lit in the evenings.","weatherNote":"Trail gets slippery when wet — if it''s rained, do it as an out-and-back rather than the crossing."}'::jsonb, '["Keihan or bus to Demachiyanagi, then Eizan Electric Railway to Kurama, ~30 min, ~¥430.","Sit at the front for the maple tunnel."]'::jsonb, '["Walk down to Kibune-guchi Station (or the local bus from Kibune, ~5 min) → Eizan line back to Demachiyanagi."]'::jsonb, '[{"name":"Kurama-dera","placeId":"f397f861-0b11-42c7-8539-120c0beb3202","note":"Cable car available for the first climb if knees object."},{"name":"Mountain trail to Kibune","note":"The tree-root path past Ōsugi-gongen."},{"name":"Kifune Shrine","placeId":"52a64dde-c84c-4eb3-aaf1-e3129adffdb8","note":"The lantern staircase — the trip''s signature photo."}]'::jsonb, '[{"name":"Hirobun, Kibune","note":"Riverside kaiseki — reserve ahead; nagashi-sōmen in warmer months only."},{"name":"Yōkihi or Beniya","note":"Simpler lunch sets in Kibune."}]'::jsonb, 'Kurama Station → Kurama-dera → ridge trail → Kibune → Kifune Shrine → Kibune-guchi Station.', 'Kurama Kibune', '["Real walking shoes","Book Kibune lunch","Start by 10:00 — daylight is short","Water + a snack"]'::jsonb),
  ('fbe52a3c-e549-49ce-9d23-0a8a0e7b1cf9', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 6, 'Arashiyama', '嵐山', 'Arashiyama', 'dt-arashiyama', 'The bamboo grove at opening before the crowds, Tenryū-ji''s borrowed-scenery garden, the Ōkōchi villa, monkeys on the hill, and the Hozu river under the Togetsukyō bridge.', '{"travelTimeMin":17,"walkKm":6,"difficulty":"moderate","elevationNote":"Flat except the 20-min uphill to the monkey park (optional).","lastTrainBack":"JR Sagano line and Randen tram to Kyoto until ~23:30.","reservation":"recommended","bestMonths":"Mid–late Nov; the Sagano Romantic Train is the best foliage ride in Kansai.","weatherNote":"Bamboo grove is magic in light rain and mist, miserable in a crowd — be there by 08:00."}'::jsonb, '["JR Sagano Line, Kyoto → Saga-Arashiyama, ~15 min, ~¥240, every ~15 min.","Or the Randen tram from Shijō-Ōmiya for the slow, scenic approach."]'::jsonb, '["JR from Saga-Arashiyama","Sagano Romantic Train Kameoka → Torokko Saga (book ahead — sells out in foliage season), then JR back."]'::jsonb, '[{"name":"Bamboo Grove","placeId":"723f61a2-2968-4460-84c4-b029cf99ebfe","note":"Before 08:00 or forget it."},{"name":"Tenryū-ji","placeId":"fe36b8e8-f651-4ac7-9c73-7533496e6299","note":"Enter from the north gate straight into the garden."},{"name":"Ōkōchi Sansō villa","note":"Tea and a sweet included in the ticket; almost empty compared to the grove."},{"name":"Sagano Romantic Train","placeId":"b0422f7d-5ffa-4c6c-8d4b-b915b6414096","note":"Open-window carriage 5 if you can get it."}]'::jsonb, '[{"name":"% Arabica Arashiyama","placeId":"fd80a8b3-e29a-4b4c-97c3-9b8f28a66a92","note":"Riverbank; queue moves fast."},{"name":"Kyoto Saryo or Musubi Café","note":"Lunch sets near the bamboo entrance."}]'::jsonb, 'Saga-Arashiyama → bamboo grove → Ōkōchi Sansō → Tenryū-ji → Togetsukyō bridge → riverside → (train option from Torokko Saga).', 'Arashiyama', '["First train out — leave by 07:15","Pre-book the Sagano train if you want it","Coins for temple entries"]'::jsonb);
insert into collections (id, trip_id, position, title, subtitle, kind, image, blurb) values
  ('9bfce6bd-9232-44d9-bc40-6e2f38421a06', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'Autumn foliage', 'Kōyō', 'theme', 'col-foliage', 'Our three weeks sit right at the front edge of the season — the mountains (Ōhara, Kurama, Kibune) turn late October, the Kyoto temples peak in the days after we leave for Tokyo. Track each spot''s colour here and chase it.'),
  ('937507ae-ba02-4c2f-bb74-3dc48f67fb59', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Coffee', 'Kissaten and third-wave', 'wishlist', 'col-coffee', 'Kyoto and Tokyo both take coffee seriously. A running list of the ones worth a detour.'),
  ('76b3a005-c015-427c-91f9-7a4ad80706fa', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'Temples & shrines', 'The ones that stayed with us', 'theme', 'col-temples', 'Not a checklist of every gate — just the ones worth the early alarm and the entrance fee.'),
  ('324b5109-1fb7-4717-88e3-632f9514ec0a', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'Gardens', 'Moss, gravel and borrowed scenery', 'theme', 'col-gardens', 'Kyoto''s real art form. Quiet, ticketed, often almost empty while the temple next door is packed.'),
  ('4686c36a-b212-4a41-b1c4-617c7fb8b647', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 4, 'Scenic trains', 'Rides that are the point, not the transfer', 'theme', 'col-trains', 'The Fuji Excursion, the Eizan maple tunnel, the Sagano Romantic Train, the Randen tram.'),
  ('3892dca3-4976-404e-b5b3-ef411d374e9d', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 5, 'Shopping', 'MUJI, Loft, Hands, Don Quijote, markets', 'wishlist', 'col-shopping', 'A wishlist by category, plus where the flagship stores are and the tax-free rules.'),
  ('08ac6cea-8f4a-49f1-85d8-26918227ccb2', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 6, 'Favourite places', 'The shortlist', 'theme', 'col-favourites', 'The handful we''d come back for. Fill this in as the trip goes.'),
  ('50088cd6-d8ea-426a-85fc-0be5d4f75a50', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 7, 'Hidden gems', 'Quiet corners', 'theme', 'col-hidden', 'Backstreets, small shrines, the temple everyone walks past. The opposite of the top-ten list.'),
  ('ffd5d20f-cd38-4d24-8ce3-defa5f243ccf', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 8, 'Museums', 'Art, history, one immersive room', 'theme', 'col-museums', 'Good rainy-day and holiday-crowd insurance.');
insert into seasonal (id, trip_id, position, date, sunset, temp_lo, temp_hi) values
  ('cf6e16b5-78e4-4b89-bf32-06b678c8853b', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, '2026-10-21', '16:56', 14, 19),
  ('6616767d-17a7-4bf4-b4ad-f405bd43e2db', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, '2026-10-22', '16:55', 14, 19),
