insert into reservations (id, trip_id, position, title, when_text, book_by, url, note, place_id) values
  ('cfd0c9f4-f0e5-4d1f-b8d1-e0d1f97fbb7d', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'Limited Express Fuji Excursion — reserved seats', '2026-10-26', '2026-10-19', 'https://www.jreast.co.jp/multi/en/', 'All seats reserved; sells out in foliage season. Book ~1 month out if possible.', NULL),
  ('7b16f290-a1e7-49b4-b1c6-9341a6bd4aa5', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Mishima ⇄ Kawaguchiko liner bus', '2026-10-28', '2026-10-26', NULL, 'Reserve at the Kawaguchiko Station window a day or two ahead — it sells out.', NULL),
  ('8b1114f0-4a1f-419a-aa83-677b86db056c', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'Hikari — Mishima → Kyoto', '2026-10-28', '2026-10-26', 'https://smart-ex.jp/en/', 'Not all Hikari stop at Mishima — choose the train, then book on smartEX.', NULL),
  ('f3b79a65-3d4c-4df1-a116-87dca2763680', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'Kibune riverside lunch (Hirobun or similar)', '2026-11-07', '2026-11-03', NULL, 'Kaiseki sets need a same-week booking, especially at weekends.', '52a64dde-c84c-4eb3-aaf1-e3129adffdb8'),
  ('55e4edb7-aa8d-4047-8121-56642269403a', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 4, 'Sagano Romantic Train — Arashiyama', '2026-10-31', '2026-10-24', NULL, 'Sells out in foliage season. Book at a JR West office or online 1 month ahead.', NULL),
  ('a4c6781d-11f4-4ca3-9a62-ee614fbf8534', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 5, 'Nozomi — Kyoto → Tokyo', '2026-11-11', '2026-11-08', 'https://smart-ex.jp/en/', 'Reserve on smartEX. No oversized-baggage seat needed — big cases go by Yamato.', NULL),
  ('f21bb766-8c24-4955-a1e6-35b5f0cf6f4b', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 6, 'Kyoto farewell dinner', '2026-11-10', '2026-11-05', NULL, 'Counter place or Pontochō — book once the day''s plan is firm.', NULL);
