insert into etiquette (id, trip_id, position, title, context, body) values
  ('b8de2275-9b14-4f94-9b40-2de1b55e8496', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 0, 'The genkan', 'Villa Yamitsuki, tea houses, some restaurants', 'Step out of your shoes in the lowered entrance, don''t step on it in socks. Point your shoes back toward the door. Use the provided slippers inside — but never on tatami, and swap to the special toilet slippers for the bathroom (and swap back).'),
  ('c7e99a9d-d2cb-486d-a408-a95dd6c861b7', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 1, 'Onsen, briefly', 'Villa Yamitsuki', 'Wash and rinse thoroughly at the seated showers first. The small towel doesn''t go in the water — fold it on your head or leave it at the edge. No phones, no photos. Tie long hair up. Tattoos: check the house rules; a cover patch usually suffices for a private or small ryokan bath.'),
  ('aed510e7-6fe6-445c-99e6-7bb8ab32f6b9', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 2, 'Temples & shrines', 'Everywhere in Kyoto', 'At a shrine torii, bow slightly and keep to the side of the path (the centre is for the gods). Purify at the water basin: left hand, right hand, a sip from the left hand, rinse the ladle upright. Photos are usually fine outside, rarely inside main halls — look for the signs.'),
  ('b4f37d61-98ab-4917-b4f3-61f2f3668e91', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 3, 'On the train', 'All the transfers', 'Talk quietly, phone on silent, no calls. Queue on the platform marks. Backpacks off and down, or on the rack. Eating is fine on the Shinkansen and limited expresses, not on local commuter trains.'),
  ('201bb973-5c63-498b-adaf-c28b66d78826', '4feb9bdb-a5bf-4fa2-8783-1cdc357dbdac', 4, 'Paying', 'Shops, restaurants, temples', 'Put cash and cards on the little tray, not into hands. No tipping — it can cause confusion. Carry coins: temple entries, lockers, small shops and Ōhara are often cash-only.');
